<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');
header('Access-Control-Allow-Origin: *');
header('Access-Control-Allow-Headers: Content-Type, Authorization');
header('Access-Control-Allow-Methods: GET, POST, PATCH, DELETE, OPTIONS');
if (($_SERVER['REQUEST_METHOD'] ?? '') === 'OPTIONS') exit;
$pdo=new PDO('mysql:host=127.0.0.1;dbname=eventflow;charset=utf8mb4','root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
function body():array{return json_decode(file_get_contents('php://input'),true)??[];}
function reply(mixed $data,int $status=200):never{http_response_code($status);echo json_encode($data,JSON_UNESCAPED_UNICODE);exit;}
function currentUser():?array{global $pdo;$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/^Bearer\s+(.+)$/i',$h,$m))return null;$q=$pdo->prepare('SELECT u.id,u.email,u.role,u.first_name,u.last_name FROM api_tokens t JOIN users u ON u.id=t.user_id WHERE t.token_hash=? AND t.expires_at>NOW()');$q->execute([hash('sha256',$m[1])]);return $q->fetch()?:null;}
function requireUser():array{$u=currentUser();if(!$u)reply(['error'=>'Connexion requise.'],401);return $u;}
function requireAdmin():array{$u=requireUser();if($u['role']!=='admin')reply(['error'=>'Accès administrateur requis.'],403);return $u;}
function requireOrganizer():array{$u=requireUser();if(!in_array($u['role'],['admin','organizer'],true))reply(['error'=>'Un compte organisateur validé est nécessaire.'],403);return $u;}
function requireEventAccess(int $id):array{global $pdo;$u=requireUser();if($u['role']==='admin')return $u;if($u['role']==='organizer'){$q=$pdo->prepare('SELECT organizer_id FROM events WHERE id=?');$q->execute([$id]);if((int)$q->fetchColumn()===(int)$u['id'])return $u;}if($u['role']==='staff'){$q=$pdo->prepare('SELECT COUNT(*) FROM event_staff WHERE event_id=? AND user_id=?');$q->execute([$id,$u['id']]);if((int)$q->fetchColumn())return $u;}reply(['error'=>'Accès refusé pour cet événement.'],403);}
function ticketSecret():string{$s=getenv('EVENTFLOW_TICKET_SECRET');if($s)return $s;$f=__DIR__.'/../api/.ticket-secret';$v=@file_get_contents($f);if(!$v){$v=random_bytes(48);@file_put_contents($f,$v,LOCK_EX);@chmod($f,0600);}return $v;}
function ensureSubscriptionSchema():void{global $pdo;
 $pdo->exec("CREATE TABLE IF NOT EXISTS plans(id VARCHAR(30) PRIMARY KEY,name VARCHAR(80) NOT NULL,monthly_price INT NOT NULL DEFAULT 0,annual_price INT NOT NULL DEFAULT 0,max_events INT NULL,max_tickets_per_event INT NULL,max_ticket_types INT NULL,max_controllers INT NULL,commission DECIMAL(5,2) NOT NULL DEFAULT 0,features JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
 $pdo->exec("CREATE TABLE IF NOT EXISTS subscriptions(id BIGINT AUTO_INCREMENT PRIMARY KEY,organizer_id INT NOT NULL,plan_id VARCHAR(30) NOT NULL,billing_period ENUM('monthly','annual') NOT NULL,status ENUM('pending_payment','active','grace','expired','cancelled','suspended') NOT NULL DEFAULT 'pending_payment',starts_at DATETIME NULL,ends_at DATETIME NULL,renewal_auto TINYINT(1) NOT NULL DEFAULT 0,adjustment_type ENUM('none','percent','fixed') NOT NULL DEFAULT 'none',adjustment_value DECIMAL(10,2) NOT NULL DEFAULT 0,adjustment_reason VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(organizer_id,status),FOREIGN KEY(organizer_id) REFERENCES users(id),FOREIGN KEY(plan_id) REFERENCES plans(id)) ENGINE=InnoDB");
 $pdo->exec("CREATE TABLE IF NOT EXISTS subscription_payments(id BIGINT AUTO_INCREMENT PRIMARY KEY,subscription_id BIGINT NOT NULL,amount INT NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'XAF',provider VARCHAR(50) NOT NULL DEFAULT 'unconfigured',provider_reference VARCHAR(190) NULL,status ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(provider_reference),FOREIGN KEY(subscription_id) REFERENCES subscriptions(id)) ENGINE=InnoDB");
 $pdo->exec("CREATE TABLE IF NOT EXISTS payment_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(50) NOT NULL,provider_event_id VARCHAR(190) NOT NULL,payload JSON NULL,processed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(provider,provider_event_id)) ENGINE=InnoDB");
 $pdo->exec("CREATE TABLE IF NOT EXISTS invoices(id BIGINT AUTO_INCREMENT PRIMARY KEY,subscription_id BIGINT NOT NULL,invoice_number VARCHAR(50) NOT NULL UNIQUE,amount INT NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'XAF',status VARCHAR(30) NOT NULL DEFAULT 'issued',pdf_path VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subscription_id) REFERENCES subscriptions(id)) ENGINE=InnoDB");
 $plans=[['free','Gratuit',0,0,1,50,1,1,7,['QR numérique','Rapports de base']],['starter','Starter',5000,50000,3,300,3,3,5,['QR numérique','Scan hors ligne','Support e-mail']],['pro','Pro',15000,150000,15,2000,null,10,3,['Scan hors ligne','Codes promo','Rapports et exports','Personnalisation']],['business','Business',40000,400000,null,null,null,null,1.5,['Toutes les fonctions','Domaine personnalisé','Support dédié']]];$q=$pdo->prepare('INSERT IGNORE INTO plans(id,name,monthly_price,annual_price,max_events,max_tickets_per_event,max_ticket_types,max_controllers,commission,features) VALUES(?,?,?,?,?,?,?,?,?,?)');foreach($plans as $p)$q->execute([$p[0],$p[1],$p[2],$p[3],$p[4],$p[5],$p[6],$p[7],$p[8],json_encode($p[9],JSON_UNESCAPED_UNICODE)]);
 foreach(['status'=>"ALTER TABLE issued_tickets ADD COLUMN status ENUM('valid','used','cancelled','refunded','expired','transferred') NOT NULL DEFAULT 'valid'",'ticket_type_id'=>"ALTER TABLE issued_tickets ADD COLUMN ticket_type_id VARCHAR(80) NULL",'entry_point'=>"ALTER TABLE issued_tickets ADD COLUMN entry_point VARCHAR(100) NULL"] as $col=>$ddl){$q=$pdo->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='issued_tickets' AND COLUMN_NAME=?");$q->execute([$col]);if(!(int)$q->fetchColumn())$pdo->exec($ddl);}
 foreach(['adjustment_type'=>"ALTER TABLE subscriptions ADD COLUMN adjustment_type ENUM('none','percent','fixed') NOT NULL DEFAULT 'none'",'adjustment_value'=>"ALTER TABLE subscriptions ADD COLUMN adjustment_value DECIMAL(10,2) NOT NULL DEFAULT 0",'adjustment_reason'=>"ALTER TABLE subscriptions ADD COLUMN adjustment_reason VARCHAR(255) NULL"] as $col=>$ddl){$q=$pdo->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='subscriptions' AND COLUMN_NAME=?");$q->execute([$col]);if(!(int)$q->fetchColumn())$pdo->exec($ddl);}
}
function ensureMessagingSchema():void{global $pdo;$pdo->exec("CREATE TABLE IF NOT EXISTS messages(id BIGINT AUTO_INCREMENT PRIMARY KEY,sender_id INT NOT NULL,recipient_id INT NOT NULL,related_event_id BIGINT NULL,body TEXT NOT NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(sender_id,recipient_id,created_at),INDEX(recipient_id,read_at),FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(recipient_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(related_event_id) REFERENCES events(id) ON DELETE SET NULL) ENGINE=InnoDB");}
function expirePendingBookings():void{global $pdo;$pdo->beginTransaction();try{$rows=$pdo->query("SELECT id,event_id,tickets FROM bookings WHERE status='pending_payment' AND expires_at<=NOW() FOR UPDATE")->fetchAll();foreach($rows as $r){$q=$pdo->prepare("UPDATE bookings SET status='expired' WHERE id=? AND status='pending_payment'");$q->execute([$r['id']]);if($q->rowCount()){$old=json_decode($r['tickets'],true)?:[];$n=array_sum(array_map('intval',$old));$pdo->prepare('UPDATE events SET available_tickets=LEAST(capacity,available_tickets+?) WHERE id=?')->execute([$n,$r['event_id']]);foreach($old as $type=>$count)$pdo->prepare('UPDATE event_ticket_types SET available_quantity=LEAST(quantity,available_quantity+?) WHERE event_id=? AND id=?')->execute([(int)$count,$r['event_id'],(string)$type]);}}$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();}}
function rateLimit(string $scope,int $limit,int $seconds):void{global $pdo;$key=hash('sha256',$scope.'|'.($_SERVER['REMOTE_ADDR']??'unknown'));$q=$pdo->prepare('INSERT INTO api_rate_limits(bucket_key,hits,window_started) VALUES(?,1,NOW()) ON DUPLICATE KEY UPDATE hits=IF(window_started<DATE_SUB(NOW(),INTERVAL ? SECOND),1,hits+1),window_started=IF(window_started<DATE_SUB(NOW(),INTERVAL ? SECOND),NOW(),window_started)');$q->execute([$key,$seconds,$seconds]);$q=$pdo->prepare('SELECT hits FROM api_rate_limits WHERE bucket_key=?');$q->execute([$key]);if((int)$q->fetchColumn()>$limit){header('Retry-After: '.$seconds);reply(['error'=>'Trop de tentatives. Réessayez plus tard.'],429);}}
